l -->\r\n  <td data-label="Skill" ng-switch="vm.selectedRoot">\r\n    <div ng-switch-when="BSKL" ng-repeat="businessSkill in item.businessSkills">\r\n      <span ng-bind="businessSkill[0]"></span>\r\n      <span ng-if="businessSkill[1]"><i class="fa fa-angle-double-right"></i> <span ng-bind="businessSkill[1]"></span></span>\r\n    </div>\r\n    <div ng-switch-when="CCAT" ng-repeat="communicativeCategory in item.communicativeCategories">\r\n      <span ng-bind="communicativeCategory[0]"></span>\r\n      <span ng-if="communicativeCategory[1]"><i class="fa fa-angle-double-right"></i> <span ng-bind="communicativeCategory[1]"></span></span>\r\n    </div>\r\n<div ng-switch-when="ASKL" ng-if="item.additionalInformation[\'Academic Skills\']">\r\n  <div ng-repeat="skill in item.additionalInformation[\'Academic Skills\'].split(\'|\') track by $index">\r\n    <span>{{ skill.split(\'>\')[0] }}</span>\r\n    <span ng-if="skill.split(\'>\')[1]">\r\n      <i class="fa fa-angle-double-right"></i>\r\n      {{ skill.split(\'>\')[1] }}\r\n    </span>\r\n  </div>\r\n</div>\r\n    <span ng-switch-default ng-repeat="tag in item.tags" ng-if="tag.tagTypeId === \'SKL\'">\r\n      <span ng-if="vm.skillMap[skill.tagId]" ng-repeat="skill in tag.tags" ng-bind="vm.skillMap[skill.tagId]"></span>\r\n    </span>\r\n  </td>\r\n\r\n  <!-- GSE -->\r\n  <td data-label="GSE">\r\n    <span ng-repeat="tag in item.gse">\r\n      <span ng-repeat="gse in tag.tags" ng-bind="gse.tagName"></span>\r\n    </span>\r\n  </td>\r\n\r\n  <!-- CEFR -->\r\n  <td data-label="CEFR" class="text-nowrap">\r\n    <span ng-repeat="tag in item.tags" ng-if="tag.tagTypeId === \'CEFR\'">\r\n      <span ng-repeat="cefr in tag.tags" ng-bind="cefr.tagName"></span>\r\n    </span>\r\n  </td>\r\n\r\n  <!-- Arrow -->\r\n  <td class="text-center">\r\n    <pe-collapse-button ng-if="item.relatedDescriptors.length || item.occupations.length || item.additionalInformation[\'Soft Skills Collaboration\'] || item.additionalInformation[\'Soft Skil